fast_pseudocode:
@triton.autotune(configs=[Config({'XBLOCK': 512}, ...), ...], key=['xnumel'])
@triton.jit
def kernel(..., XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)
    ...

# CORRECT: grid is a lambda that reads meta['XBLOCK']
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](..., xnumel)

@triton.autotune(
    configs=[Config({'XBLOCK': 512}, num_warps=4), ..., Config({'XBLOCK': 2048}, num_warps=16)],
    key=['xnumel'],
)
@triton.jit
def kernel(in_out_ptr0, in_ptr0, ..., xnumel, XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)[:]
    xmask = xindex < xnumel  # added masking
    tl.store(..., xmask)

grid = (triton.cdiv(xnumel, 128),)  # grid NOT updated to use meta['XBLOCK']
kernel[grid](...)  # XBLOCK injected by autotune
